module potato_optimizer (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] N,\n    input [3:0] L,\n    input [7:0] a_0, input [7:0] a_1, input [7:0] a_2, input [7:0] a_3,\n    input [7:0] a_4, input [7:0] a_5, input [7:0] a_6, input [7:0] a_7,\n    input [19:0] c_0, input [19:0] c_1, input [19:0] c_2, input [19:0] c_3,\n    input [19:0] c_4, input [19:0] c_5, input [19:0] c_6, input [19:0] c_7,\n    output reg [31:0] result,\n    output reg done\n);\n\n    localparam [2:0] IDLE     = 3'd0;\n    localparam [2:0] COMPUTE  = 3'd1;\n    localparam [2:0] CALCULATE = 3'd2;\n    localparam [2:0] FINISH   = 3'd3;\n\n    reg [2:0] state;\n    reg [7:0] total_potatoes_reg;\n    reg [19:0] total_cost_reg;\n    reg [3:0] bag_index;\n    reg [3:0] calc_phase;\n    reg [4:0] check_k;\n    reg [8:0] potato_index;\n    reg [31:0] best_product;\n\n    reg [19:0] dp_cost [0:8][0:500];  // [bags][potatoes]\n    reg dp_valid [0:8][0:500];\n    reg [7:0] a_arr [0:7];\n    reg [19:0] c_arr [0:7];\n    integer i, j;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            total_potatoes_reg <= 8'd0;\n            total_cost_reg <= 20'd0;\n            bag_index <= 4'd0;\n            calc_phase <= 4'd0;\n            best_product <= 32'h7FFF_FFFF;\n            check_k <= 5'd0;\n            potato_index <= 9'd0;\n\n            for (i = 0; i <= 8; i = i + 1) begin\n                for (j = 0; j <= 500; j = j + 1) begin\n                    dp_cost[i][j] <= 20'd0;\n                    dp_valid[i][j] <= 1'b0;\n                end\n            end\n            dp_valid[0][0] <= 1'b1;\n        end\n        else begin\n            case(state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Load input arrays\n                        a_arr[0] <= a_0;\n                        a_arr[1] <= a_1;\n                        a_arr[2] <= a_2;\n                        a_arr[3] <= a_3;\n                        a_arr[4] <= a_4;\n                        a_arr[5] <= a_5;\n                        a_arr[6] <= a_6;\n                        a_arr[7] <= a_7;\n\n                        c_arr[0] <= c_0;\n                        c_arr[1] <= c_1;\n                        c_arr[2] <= c_2;\n                        c_arr[3] <= c_3;\n                        c_arr[4] <= c_4;\n                        c_arr[5] <= c_5;\n                        c_arr[6] <= c_6;\n                        c_arr[7] <= c_7;\n\n                        // Reset dynamic programming array\n                        for (i = 1; i <= 8; i = i + 1) begin\n                            for (j = 0; j <= 500; j = j + 1) begin\n                                dp_valid[i][j] <= 1'b0;\n                            end\n                        end\n                        state <= COMPUTE;\n                        bag_index <= 4'd0;\n                    end\n                end\n\n                COMPUTE: begin\n                    if (bag_index < N) begin\n                        for (i = N; i >= 1; i = i - 1) begin\n                            for (j = 500; j >= a_arr[bag_index]; j = j - 1) begin\n                                if (dp_valid[i-1][j - a_arr[bag_index]]) begin\n                                    if ((!dp_valid[i][j]) || (dp_cost[i-1][j - a_arr[bag_index]] + c_arr[bag_index] < dp_cost[i][j])) begin\n                                        dp_cost[i][j] <= dp_cost[i-1][j - a_arr[bag_index]] + c_arr[bag_index];\n                                        dp_valid[i][j] <= 1'b1;\n                                    end\n                                end\n                            end\n                        end\n                        bag_index <= bag_index + 1;\n                    end\n                    else begin\n                        state <= CALCULATE;\n                        check_k <= 5'd0;\n                        potato_index <= 9'd0;\n                    end\n                end\n\n                CALCULATE: begin\n                    if (check_k <= N) begin\n                        // Check partitions with L bags\n                        if (check_k == L) begin\n                            if (potato_index <= 9'd500) begin\n                                if (dp_valid[check_k][potato_index] && dp_valid[N-check_k][total_potatoes_reg - potato_index]) begin\n                                    if (potato_index > 8'd0 && (total_potatoes_reg - potato_index) > 8'd0) begin\n                                        // Calculate quality product (16.16 format)\n                                        reg [19:0] cost1 = dp_cost[check_k][potato_index];\n                                        reg [19:0] cost2 = dp_cost[N-check_k][total_potatoes_reg - potato_index];\n                                        reg [29:0] potatoes_product = potato_index * (total_potatoes_reg - potato_index);\n                                        reg [39:0] scaled_product = ((cost1 * cost2) << 16) / potatoes_product;\n\n                                        if (scaled_product < best_product) begin\n                                            best_product <= scaled_product[31:0];\n                                        end\n                                    end\n                                end\n                                potato_index <= potato_index + 1;\n                            end\n                            else begin\n                                potato_index <= 9'd0;\n                                check_k <= check_k + 1;\n                            end\n                        end\n                        else begin\n                            check_k <= check_k + 1;\n                        end\n                    end\n                    else begin\n                        result <= best_product;\n                        state <= FINISH;\n                        done <= 1'b1;\n                    end\n                end\n\n                FINISH: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\n    // Combinational total calculations\n    always @(*) begin\n        total_potatoes_reg = 0;\n        total_cost_reg = 0;\n        for (integer k = 0; k < 8; k = k + 1) begin\n            if (k < N) begin\n                total_potatoes_reg = total_potatoes_reg + a_arr[k];\n                total_cost_reg = total_cost_reg + c_arr[k];\n            end\n        end\n    end\n\nendmodule